export function isPrime(n: number): boolean {
  if (!Number.isInteger(n) || n < 2) return false;
  if (n < 4) return true;
  if (n % 2 === 0 || n % 3 === 0) return false;
  for (let i = 5; i * i <= n; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) return false;
  }
  return true;
}

/** Number of positive divisors ("factors") of n. */
export function countFactors(n: number): number {
  if (n < 1) return 0;
  let count = 0;
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) count += i * i === n ? 1 : 2;
  }
  return count;
}

/** Sum of the factors of n, excluding n itself. */
export function sumProperFactors(n: number): number {
  if (n < 2) return 0;
  let sum = 1;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) {
      sum += i;
      if (i * i !== n) sum += n / i;
    }
  }
  return sum;
}

/** Prime factorisation as a list with repeats, e.g. 12 → [2, 2, 3]. */
export function primeFactors(n: number): number[] {
  const out: number[] = [];
  let m = n;
  for (let p = 2; p * p <= m; p++) {
    while (m % p === 0) {
      out.push(p);
      m /= p;
    }
  }
  if (m > 1) out.push(m);
  return out;
}

export function isSquare(n: number): boolean {
  if (n < 0) return false;
  const r = Math.round(Math.sqrt(n));
  return r * r === n;
}

export function isCube(n: number): boolean {
  if (n < 0) return false;
  const r = Math.round(Math.cbrt(n));
  return r * r * r === n;
}

export function isTriangular(n: number): boolean {
  // n = k(k+1)/2  ⇔  8n + 1 is a perfect square
  return n >= 1 && isSquare(8 * n + 1);
}

export function isFibonacci(n: number): boolean {
  if (n < 1) return false;
  let a = 1;
  let b = 2;
  while (a < n) [a, b] = [b, a + b];
  return a === n;
}

/** True if n = base^k for some whole k ≥ 1. */
export function isPowerOf(n: number, base: number): boolean {
  if (n < base) return false;
  let m = n;
  while (m % base === 0) m /= base;
  return m === 1;
}

export function isFactorial(n: number): boolean {
  let f = 1;
  for (let k = 1; f < n; k++) f *= k + 1;
  return f === n && n >= 1;
}

export function digitsOf(n: number): number[] {
  return String(Math.abs(n)).split('').map(Number);
}

export function digitSum(n: number): number {
  return digitsOf(n).reduce((a, b) => a + b, 0);
}

export function digitProduct(n: number): number {
  return digitsOf(n).reduce((a, b) => a * b, 1);
}

export function reverseDigits(n: number): number {
  return Number(String(n).split('').reverse().join(''));
}

export function isPalindrome(n: number): boolean {
  return reverseDigits(n) === n;
}

export function digitsStrictlyAscending(n: number): boolean {
  const d = digitsOf(n);
  return d.every((x, i) => i === 0 || x > d[i - 1]!);
}

export function allDigitsSame(n: number): boolean {
  const d = digitsOf(n);
  return d.length > 1 && d.every((x) => x === d[0]);
}

export function isHarshad(n: number): boolean {
  return n > 0 && n % digitSum(n) === 0;
}

export function isAbundant(n: number): boolean {
  return sumProperFactors(n) > n;
}

export function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

/** n = a² + b² with whole numbers a, b ≥ 1. */
export function isSumOfTwoSquares(n: number): boolean {
  for (let a = 1; a * a < n; a++) {
    if (isSquare(n - a * a) && n - a * a >= 1) return true;
  }
  return false;
}

/** n = a³ + b³ with whole numbers a, b ≥ 1. */
export function isSumOfTwoCubes(n: number): boolean {
  for (let a = 1; a * a * a < n; a++) {
    if (isCube(n - a * a * a) && n - a * a * a >= 1) return true;
  }
  return false;
}

/** n = a² − b² with whole numbers a > b ≥ 0. True exactly when n is not 2 more than a multiple of 4. */
export function isDifferenceOfTwoSquares(n: number): boolean {
  return n >= 1 && n % 4 !== 2;
}

/** Product of exactly `count` different primes, each used once. */
export function isProductOfDistinctPrimes(n: number, count: number): boolean {
  const f = primeFactors(n);
  return f.length === count && new Set(f).size === count;
}
